#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
printf '%s\n' '=== Text Processing Commands ==='
file_content="$(cat 000__04c_text_processing_commands.sh | head -5)"
printf '%s\n' 'First 5 lines of this file:'
printf '%s\n' "$file_content"
grep_result="$(grep -n echo 000__04c_text_processing_commands.sh)"
printf '%s\n' 'Lines containing '\''echo'\'':'
printf '%s\n' "$grep_result"
sed_result="$(echo 'Hello World' | sed s/World/Universe/)"
printf '%s\n' "Sed result: $sed_result"
awk_result="$(echo '1 2 3 4 5' | awk '{print $1 + $2}')"
printf '%s\n' "Awk sum result: $awk_result"
sort_result="$(printf '%b\n' 'zebra\napple\nbanana' | sort)"
printf '%s\n' 'Sorted words:'
printf '%s\n' "$sort_result"
uniq_result="$(printf '%b\n' 'apple\napple\nbanana\nbanana\ncherry' | uniq)"
printf '%s\n' 'Unique words:'
printf '%s\n' "$uniq_result"
word_count="$(echo 'Hello World' | wc -w)"
line_count="$(printf '%b\n' 'line1\nline2\nline3' | wc -l)"
printf '%s\n' "Word count: $word_count"
printf '%s\n' "Line count: $line_count"
head_result="$(seq 1 10 | head -3)"
printf '%s\n' "First 3 numbers: $head_result"
tail_result="$(seq 1 10 | tail -3)"
printf '%s\n' "Last 3 numbers: $tail_result"
cut_result="$(echo apple:banana:cherry | cut -d : -f 2)"
printf '%s\n' "Second field: $cut_result"
printf '%s' '1
2
3
' > temp1.txt
printf '%s' 'a
b
c
' > temp2.txt
paste_result="$(paste temp1.txt temp2.txt)"
printf '%s\n' 'Pasted columns:'
printf '%s\n' "$paste_result"
rm -f temp1.txt temp2.txt
printf '%s' 'apple
banana
cherry
' > file1.txt
printf '%s' 'banana
cherry
date
' > file2.txt
comm_result="$(comm -12 file1.txt file2.txt)"
printf '%s\n' 'Common lines:'
printf '%s\n' "$comm_result"
diff_result="$(diff file1.txt file2.txt)"
printf '%s\n' 'File differences:'
printf '%s\n' "$diff_result"
d="$(mktemp -d)"
cd "$d" || exit 1
tr_result="$(echo 'HELLO WORLD' | tr A-Z a-z)"
printf '%s\n' "Lowercase: $tr_result"
xargs_result="$(echo '1 2 3' | xargs -n 1 echo Number:)"
printf '%s\n' 'Xargs result:'
printf '%s\n' "$xargs_result"
rm -f file1.txt file2.txt
cd /
rm -r -f "$d"
printf '%s\n' '=== Text Processing Commands Complete ==='
